@Override public Socket createSocket(final InetAddress inetAddress,final int port,final InetAddress localHost,final int localPort) throws IOException {
  try {
    final Socket socket=this.factory(inetAddress.getHostName()).createSocket(inetAddress,port,localHost,localPort);
    configurator.configure(socket);
    return socket;
  } catch (RuntimeException e) {
    throw new IOException("Socket creation failed due to runtime exception", e);
  }
}
